sys_ws_operation.operation_script:
(function process( /*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    try {
        var formData = request.queryParams;

        var requestBody = gs.base64Decode(formData.request);
        requestBody = decodeURIComponent(requestBody);
        //var requestBody = formData.request;
        var data = {};

        var reqBody = JSON.parse(requestBody);
        var tradeid = reqBody.tradeid;
        var market = reqBody.market;
        var clientidentifier = reqBody.clientidentifier;
        var eventdatetime = reqBody.eventdatetime;
        var responseBody = {};

        if (tradeid == '' || tradeid == undefined) {
            responseBody.message = 'Missing Trade Id';
            response.setBody(responseBody);
            response.setStatus(400);
            return;
        }

        if (market == '' || market == undefined) {
            responseBody.message = 'Missing Market';
            response.setBody(responseBody);
            response.setStatus(400);
            return;
        }

        if (clientidentifier == '' || clientidentifier == undefined) {
            responseBody.message = 'Missing Client Identifier';
            response.setBody(responseBody);
            response.setStatus(400);
            return;
        }

        if (eventdatetime == '' || eventdatetime == undefined) {
            responseBody.message = 'Missing Event Date/Time';
            response.setBody(responseBody);
            response.setStatus(400);
            return;
        }

        var grWidget;
        grWidget = new GlideRecord('x_hsb11_hsbc_mss_o_mss_widget_inbound');
        grWidget.initialize();
        grWidget.object_id = tradeid;
        grWidget.object_version = '1';
        grWidget.object_type = 'AUTOMATED_QUERY_REQUEST';
        //grWidget.object_id_type = requestData.objectidtype;
        grWidget.event_status = 'AUTOMATED_QUERY';
        grWidget.source = 'TASKIZE';
        grWidget.message_id = tradeid;
        grWidget.event_type = 'TASKIZE_AUTOMATED_QUERY';
        grWidget.payload = JSON.stringify(reqBody);

        //mapping table to check access with clientidentifier and market
        var authenticateQuery = new GlideRecord('x_hsb11_mss_taskiz_mss_taskize_automated_query_authentication');
        authenticateQuery.addEncodedQuery('lei=' + clientidentifier /*+ '^market=' + market*/ );
        authenticateQuery.query();
        if (authenticateQuery.next()) {

            var grTrade = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
            grTrade.addEncodedQuery('transaction_reference=' + tradeid + '^owning_business=' + market + '^NQcustomer_reference=' + tradeid + '^owning_business=' + market);
            grTrade.orderByDesc('sys_created_on');
            grTrade.setLimit(1);
            grTrade.query();
            if (grTrade.next()) {

                if ((grTrade.mis_group == authenticateQuery.mis_group) && (grTrade.enitity_code == authenticateQuery.entity_code)) {

                    responseBody.transaction_reference = grTrade.transaction_reference ? grTrade.transaction_reference.toString() : "";
                    responseBody.customer_reference = grTrade.customer_reference ? grTrade.customer_reference.toString() : "";
                    responseBody.securities_account = grTrade.securities_account ? grTrade.securities_account.toString() : "";
                    responseBody.trade_date = grTrade.trade_date ? grTrade.trade_date.toString() : "";
                    responseBody.settlement_date = grTrade.settlement_date ? grTrade.settlement_date.toString() : "";
                    responseBody.isin = grTrade.isin ? grTrade.isin.toString() : "";
                    responseBody.reason_code = grTrade.reason_code.getDisplayValue() ? grTrade.reason_code.getDisplayValue().toString() : "";
                    responseBody.reason_description = grTrade.reason_description_remarks_unex ? grTrade.reason_description_remarks_unex.toString() : "";
                    responseBody.transaction_type = grTrade.transaction_type.getDisplayValue() ? grTrade.transaction_type.getDisplayValue().toString() : "";
                    responseBody.security_id = grTrade.security_id ? grTrade.security_id.toString() : "";
                    responseBody.settlement_quantity = grTrade.settlement_quantity ? grTrade.settlement_quantity.toString() : "";
                    responseBody.settlement_amount = grTrade.settlement_amount ? grTrade.settlement_amount.toString() : "";
                    responseBody.settlement_amount_currency = grTrade.settlement_amount_currency.getDisplayValue() ? grTrade.settlement_amount_currency.getDisplayValue().toString() : "";
                    responseBody.counterparty_name = grTrade.counterparty_name ? grTrade.counterparty_name.toString() : "";
                    responseBody.trade_lifecycle_status = grTrade.trade_lifecycle_status.getDisplayValue() ? grTrade.trade_lifecycle_status.getDisplayValue().toString() : "";

                    response.setBody(responseBody);
                    response.setStatus(200);

                    data.response = responseBody;
                    data.clientname = authenticateQuery.client_name.toString();
                    //data.owningbusiness = authenticateQuery.owning_business.toString();
                    data.owningbusiness = market.toString();

                    grWidget.status = 'Success';
                    grWidget.additional_attributes = JSON.stringify(data);
                    grWidget.event_date_time = new GlideDateTime();
                    grWidget.insert();

                    gs.eventQueue('x_hsb11_mss_taskiz.create_taskize_case', grWidget, grWidget.event_status, grWidget.sys_id);

                    return;

                } else {

                    //responseBody.message = 'Client does not have access to view trade details';
                    responseBody.message = 'Could not find any trade details matching the information provided. Kindly raise a manual query for further assistance';
                    response.setBody(responseBody);
                    response.setStatus(400);

                    data.response = responseBody;
                    data.clientname = authenticateQuery.client_name.toString();
                    data.owningbusiness = market.toString();

                    grWidget.status = 'Error';
                    grWidget.additional_attributes = JSON.stringify(data);
                    grWidget.event_date_time = new GlideDateTime();
                    grWidget.insert();

                    gs.eventQueue('x_hsb11_mss_taskiz.create_taskize_case', grWidget, grWidget.event_status, grWidget.sys_id);

                    return;
                }
            } else {
				gs.info('Taskize 128');
                var grPassiveTrade = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade_passive');
                grPassiveTrade.addEncodedQuery('transaction_reference=' + tradeid + '^owning_business=' + market + '^NQcustomer_reference=' + tradeid + '^owning_business=' + market);
                grPassiveTrade.orderByDesc('sys_created_on');
                grPassiveTrade.setLimit(1);
                grPassiveTrade.query();
                if (grPassiveTrade.next()) {
					gs.info('Taskize passive trade found');
                    if ((grPassiveTrade.mis_group == authenticateQuery.mis_group) && (grPassiveTrade.enitity_code == authenticateQuery.entity_code)) {
						gs.info('Taskize condition failed :'+ grPassiveTrade.mis_group + authenticateQuery.mis_group + grPassiveTrade.enitity_code + authenticateQuery.entity_code);
                        responseBody.transaction_reference = grPassiveTrade.transaction_reference ? grPassiveTrade.transaction_reference.toString() : "";
                        responseBody.customer_reference = grPassiveTrade.customer_reference ? grPassiveTrade.customer_reference.toString() : "";
                        responseBody.securities_account = grPassiveTrade.securities_account ? grPassiveTrade.securities_account.toString() : "";
                        responseBody.trade_date = grPassiveTrade.trade_date ? grPassiveTrade.trade_date.toString() : "";
                        responseBody.settlement_date = grPassiveTrade.settlement_date ? grPassiveTrade.settlement_date.toString() : "";
                        responseBody.isin = grPassiveTrade.isin ? grPassiveTrade.isin.toString() : "";
                        responseBody.reason_code = grPassiveTrade.reason_code.getDisplayValue() ? grPassiveTrade.reason_code.getDisplayValue().toString() : "";
                        responseBody.reason_description = grPassiveTrade.reason_description_remarks_unex ? grPassiveTrade.reason_description_remarks_unex.toString() : "";
                        responseBody.transaction_type = grPassiveTrade.transaction_type.getDisplayValue() ? grPassiveTrade.transaction_type.getDisplayValue().toString() : "";
                        responseBody.security_id = grPassiveTrade.security_id ? grPassiveTrade.security_id.toString() : "";
                        responseBody.settlement_quantity = grPassiveTrade.settlement_quantity ? grPassiveTrade.settlement_quantity.toString() : "";
                        responseBody.settlement_amount = grPassiveTrade.settlement_amount ? grPassiveTrade.settlement_amount.toString() : "";
                        responseBody.settlement_amount_currency = grPassiveTrade.settlement_amount_currency.getDisplayValue() ? grPassiveTrade.settlement_amount_currency.getDisplayValue().toString() : "";
                        responseBody.counterparty_name = grPassiveTrade.counterparty_name ? grPassiveTrade.counterparty_name.toString() : "";
                        responseBody.trade_lifecycle_status = grPassiveTrade.trade_lifecycle_status.getDisplayValue() ? grPassiveTrade.trade_lifecycle_status.getDisplayValue().toString() : "";

                        response.setBody(responseBody);
                        response.setStatus(200);

                        data.response = responseBody;
                        data.clientname = authenticateQuery.client_name.toString();
                        //data.owningbusiness = authenticateQuery.owning_business.toString();
                        data.owningbusiness = market.toString();

                        grWidget.status = 'Success';
                        grWidget.additional_attributes = JSON.stringify(data);
                        grWidget.event_date_time = new GlideDateTime();
                        grWidget.insert();

                        gs.eventQueue('x_hsb11_mss_taskiz.create_taskize_case', grWidget, grWidget.event_status, grWidget.sys_id);

                        return;

                    } else {

                        //responseBody.message = 'Client does not have access to view trade details';
                        responseBody.message = 'Could not find any trade details matching the information provided. Kindly raise a manual query for further assistance';
                        response.setBody(responseBody);
                        response.setStatus(400);

                        data.response = responseBody;
                        data.clientname = authenticateQuery.client_name.toString();
                        data.owningbusiness = market.toString();

                        grWidget.status = 'Error';
                        grWidget.additional_attributes = JSON.stringify(data);
                        grWidget.event_date_time = new GlideDateTime();
                        grWidget.insert();

                        gs.eventQueue('x_hsb11_mss_taskiz.create_taskize_case', grWidget, grWidget.event_status, grWidget.sys_id);

                        return;
                    }
                } else {

                    responseBody.message = 'Could not find any trade details matching the information provided. Kindly raise a manual query for further assistance';
                    response.setBody(responseBody);
                    response.setStatus(400);

                    data.response = responseBody;
                    data.clientname = authenticateQuery.client_name.toString();
                    data.owningbusiness = market.toString();

                    grWidget.status = 'Error';
                    grWidget.additional_attributes = JSON.stringify(data);
                    grWidget.event_date_time = new GlideDateTime();
                    grWidget.insert();

                    gs.eventQueue('x_hsb11_mss_taskiz.create_taskize_case', grWidget, grWidget.event_status, grWidget.sys_id);

                    return;
                }
            }
        } else {

            //responseBody.message = 'Client is not onboarded in iQube or CLient does not have access to specified market';
            responseBody.message = 'Could not find any trade details matching the information provided. Kindly raise a manual query for further assistance';
            response.setBody(responseBody);
            response.setStatus(400);

            data.response = responseBody;
            data.clientname = authenticateQuery.client_name ? authenticateQuery.client_name.toString() : "";
            data.owningbusiness = market ? market.toString() : "";

            grWidget.status = 'Error';
            grWidget.additional_attributes = JSON.stringify(data);
            grWidget.event_date_time = new GlideDateTime();
            grWidget.insert();

            gs.eventQueue('x_hsb11_mss_taskiz.create_taskize_case', grWidget, grWidget.event_status, grWidget.sys_id);

            return;
        }
    } catch (e) {
        gs.info('Scripted REST API Resource - el_inbound_event_taskize_automated : Unkonwn exception while processing Taskize Automated Request ' + e.message);
        response.setError(new sn_ws_err.BadRequestError(e.message));
        response.setStatus(400);
        return;
    }

})(request, response);
